/*
 * prog38_continued_fraction.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program reads two integer arguments,
 * validates them and prints the continued‑fraction representation of the
 * rational number a/b in the form
 *
 *     [q0; q1, q2, ... , qn]
 *
 * where the q's are the quotients produced by the Euclidean algorithm.
 *
 * Error handling (exact strings taken from the original binary):
 *
 *   - No arguments (argc < 3)                -> "NO_INPUT"
 *   - Non‑numeric argument (strtol failure) -> "BAD_INPUT"
 *   - Denominator == 0                       -> "ERROR"
 *   - |denominator| > 100000                 -> "OUT_OF_RANGE"
 *
 * The output is terminated by a newline (as produced by puts()).
 *
 * The implementation follows the logic that was reconstructed from the
 * decompiled state‑machine in the original binary, but it is written in
 * clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

int main(int argc, char **argv)
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse first argument (numerator) ---------- */
    char *endptr1;
    errno = 0;
    long long num = strtoll(argv[1], &endptr1, 10);
    if (errno != 0 || *endptr1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse second argument (denominator) ---------- */
    char *endptr2;
    errno = 0;
    long long den = strtoll(argv[2], &endptr2, 10);
    if (errno != 0 || *endptr2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- denominator zero ---------- */
    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    /* ---------- range check (|denominator| > 100000) ---------- */
    if (llabs(den) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- normalise sign: make denominator positive ---------- */
    if (den < 0) {
        den = -den;
        num = -num;
    }

    /* ---------- Euclidean algorithm – build continued fraction ---------- */
    long long cf[201];          /* enough for all inputs the original program handled */
    int cf_len = 0;

    long long a = num;
    long long b = den;

    while (b != 0) {
        long long q = a / b;               /* C truncates toward zero – matches original */
        cf[cf_len++] = q;
        long long r = a - q * b;           /* remainder */
        a = b;
        b = r;
    }

    /* ---------- output in the required format ---------- */
    putchar('[');
    if (cf_len > 0) {
        printf("%lld", cf[0]);             /* first term */
        if (cf_len > 1) {
            printf("; ");
            for (int i = 1; i < cf_len; ++i) {
                printf("%lld", cf[i]);
                if (i != cf_len - 1)
                    printf(", ");
            }
        }
    }
    puts("]");

    return 0;
}
